    local function VM_Il0O(d, k, m)
        local R_I1OO0ll = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_I1OO0ll, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_I1OO0ll)
    end

    -- Execution Guard
    local F_OO1l00 = loadstring(VM_Il0O(B_0lOO0lOI, 53, 5))
    if F_OO1l00 then
        F_OO1l00(...)
    end
end)(...)
